import json,pathlib,html
p=pathlib.Path(__file__).parent
data=json.loads((p/'inventory.json').read_text())
entries=data['entries']
decisions=json.loads((p/'decisions.json').read_text()) if (p/'decisions.json').exists() else {'deleted':{}}
for e in entries:e['deleted_at']=decisions['deleted'].get(e['id'])
# Preserve source strings; qualify declarations that are retained only for an old redirect.
for e in entries:
 e['note']=''
 if e['type']=='页面副标题' and e['location']=='QQ 空间':e['note']='旧独立页面的定义；当前入口已重定向到「主动互动 / QQ 空间」。'
 if e['visibility']!='界面或条件显示':e['note']=e['visibility']+'；不占普通页面视觉空间。'
 if e['page']=='共享组件' and e['file'].endswith('console.jsx'):e['note']='共享组件动态容器；实际文案在调用页面中列出。'
(p/'inventory.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
subtitles=[e for e in entries if e['type'] in ['副标题','页面副标题']]
md='# 副标题清单\n\n共 '+str(len(subtitles))+' 处。编号与完整清单一致；条件分支以 / 分隔，动态内容以〔表达式〕表示。已执行的删除会标注，原编号保留。\n\n'
for e in subtitles:md+=f"- **{e['id']}｜{e['page']}｜{e['location']}｜{'已删除' if e.get('deleted_at') else '待审阅'}**\n\n  {e['text']}\n\n"
(p/'SUBTITLES.md').write_text(md.rstrip()+'\n')
json_text=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
page=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HayBot 前端文案审阅</title><style>
:root{color-scheme:light dark;--bg:#f7f7f7;--card:#fff;--fg:#171717;--muted:#666;--line:#dedede;--accent:#b4232c;--selected:#fff0f0}html[data-theme=dark]{--bg:#151515;--card:#202020;--fg:#eee;--muted:#aaa;--line:#3c3c3c;--accent:#ff8d93;--selected:#38262a;color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}button,input,select{font:inherit;color:inherit}button,select,input[type=search]{background:var(--card);border:1px solid var(--line);border-radius:7px;padding:7px 11px}button{cursor:pointer}button:hover,select:hover{border-color:var(--muted)}button.active{background:var(--fg);color:var(--card);border-color:var(--fg)}header{max-width:1500px;margin:auto;padding:28px 30px 15px}.heading{display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:25px;letter-spacing:-.5px;margin:0}header p{margin:12px 0 0;color:var(--muted)}.toolbar{position:sticky;top:0;z-index:2;background:var(--bg);border-bottom:1px solid var(--line);padding:12px 30px}.toolbar-inner{max-width:1440px;margin:auto;display:flex;gap:9px;flex-wrap:wrap}.toolbar input[type=search]{flex:1;min-width:220px}.quick{max-width:1500px;margin:0 auto;padding:16px 30px;display:flex;gap:8px;flex-wrap:wrap;align-items:center}.quick span{color:var(--muted);margin-left:auto}main{max-width:1500px;margin:auto;padding:0 30px 80px}.entry{display:grid;grid-template-columns:70px minmax(0,1fr);gap:14px;padding:19px 20px;background:var(--card);border:1px solid var(--line);border-bottom:0}.entry:first-child{border-radius:9px 9px 0 0}.entry:last-child{border-bottom:1px solid var(--line);border-radius:0 0 9px 9px}.deleted-badge{color:var(--muted);border:1px solid var(--line);border-radius:4px;padding:1px 6px}.entry.deleted .copy{text-decoration:line-through;color:var(--muted)}.entry.selected{background:var(--selected)}.number{font:600 13px ui-monospace,monospace;display:flex;flex-direction:column;align-items:flex-start;gap:9px;scroll-margin:150px}.number label{font:12px/1.5 -apple-system,sans-serif;cursor:pointer;color:var(--accent);display:flex;align-items:center;gap:4px}.number input{accent-color:var(--accent);margin:0}.meta{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:12px;color:var(--muted)}.type{padding:1px 6px;border:1px solid var(--line);border-radius:4px}.location{margin:5px 0 8px;font-size:13px;font-weight:600}.copy{white-space:pre-wrap;overflow-wrap:anywhere;font-size:15px;line-height:1.8;margin:0}.source{font:11px/1.7 ui-monospace,monospace;color:var(--muted);margin-top:10px;overflow-wrap:anywhere}.note{font-size:12px;color:var(--muted);margin-top:8px}.empty{padding:45px;text-align:center;color:var(--muted)}.selection{position:fixed;bottom:0;background:var(--card);border-top:1px solid var(--line);padding:12px 30px;display:flex;gap:10px;width:100%;z-index:3;align-items:center;box-shadow:0 -3px 14px #00000008}.selection b{margin-right:auto}.selection button{padding:5px 10px}#status{color:var(--muted);font-size:12px}.ghost{background:transparent}.count{font-size:12px;color:var(--muted)}.legend{font-size:12px!important}.hidden{display:none!important}@media(max-width:650px){header{padding:20px 16px 12px}.toolbar{padding:10px 16px}.quick{padding:12px 16px}.quick span{margin-left:0}main{padding:0 12px 100px}.entry{grid-template-columns:48px minmax(0,1fr);padding:14px 12px;gap:9px}.selection{padding:10px 15px;flex-wrap:wrap}.selection b{font-size:12px}h1{font-size:21px}.heading{align-items:flex-start}#status{width:100%;order:3}}
</style><body><header><div class="heading"><h1>前端文案审阅 <span class="count">2026.10.28</span></h1><button id="theme" aria-label="切换明暗主题">切换深色</button></div><p id="intro"></p><p class="legend">按编号告诉我删哪些，或勾选后复制待删清单。勾选只保存在当前浏览器，不修改产品。〔…〕代表动态值， / 分隔条件分支。</p></header><div class="toolbar"><div class="toolbar-inner"><input id="search" type="search" aria-label="搜索文案" placeholder="搜索原文、编号、页面或源码文件"><select id="page" aria-label="按页面筛选"><option value="">全部页面</option></select><select id="type" aria-label="按文案类型筛选"><option value="">全部类型</option></select></div></div><div class="quick"><button data-mode="subtitles" class="active">副标题</button><button data-mode="core">全部主要说明</button><button data-mode="extra">补充候选与反馈</button><button data-mode="all">完整清单</button><button data-mode="selected">仅看待删</button><button data-mode="deleted">已删除</button><span id="counter"></span></div><main><div id="list"></div></main><div class="selection"><b id="selected-count">待删 0 项</b><span id="status" role="status"></span><button id="copy">复制待删编号</button><button id="download">导出待删清单</button><button id="clear" class="ghost">清空勾选</button></div><script id="inventory" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('inventory').textContent),items=data.entries,extras=new Set(['补充文案候选','行内说明候选','操作反馈与确认']),$=id=>document.getElementById(id);let mode='subtitles',selected=new Set;try{selected=new Set(JSON.parse(localStorage.getItem('haybot-copy-review-20261028')||'[]').filter(id=>!items.some(e=>e.id===id&&e.deleted_at)))}catch{}const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const name of [...new Set(items.map(e=>e.page))])$('page').add(new Option(name,name));for(const name of [...new Set(items.map(e=>e.type))])$('type').add(new Option(name,name));
const subtitleCount=items.filter(e=>e.type.includes('副标题')).length,coreCount=items.filter(e=>!extras.has(e.type)).length;$('intro').textContent=`${items.filter(e=>e.deleted_at).length} 项已删除，原文和编号保留。${subtitleCount} 处副标题 · ${coreCount} 项主要说明 · ${items.length-coreCount} 项补充候选与反馈。覆盖 frontend/src 全部 JS / JSX；未包含真实聊天、日记和用户填写的内容。`;
function updateSelection(){try{localStorage.setItem('haybot-copy-review-20261028',JSON.stringify([...selected]))}catch{}$('selected-count').textContent=`待删 ${selected.size} 项`;}
function render(){const q=$('search').value.trim().toLowerCase(),page=$('page').value,type=$('type').value;const matches=items.filter(e=>(!page||e.page===page)&&(!type||e.type===type)&&(!q||[e.id,e.page,e.type,e.location,e.text,e.file,e.note].join(' ').toLowerCase().includes(q))&&(mode==='all'||mode==='subtitles'&&e.type.includes('副标题')||mode==='core'&&!extras.has(e.type)||mode==='extra'&&extras.has(e.type)||mode==='selected'&&selected.has(e.id)||mode==='deleted'&&e.deleted_at));$('counter').textContent=`当前 ${matches.length} / 共 ${items.length} 项`;$('list').innerHTML=matches.length?matches.map(e=>`<article class="entry ${selected.has(e.id)?'selected':''} ${e.deleted_at?'deleted':''}" id="${e.id}"><div class="number">${e.id}<label><input type="checkbox" data-id="${e.id}" ${selected.has(e.id)?'checked':''} ${e.deleted_at?'disabled':''} aria-label="将 ${e.id} 标为待删">待删</label></div><div><div class="meta"><span>${esc(e.page)}</span><span class="type">${e.type}</span>${e.deleted_at?`<span class="deleted-badge">已删除 · ${e.deleted_at}</span>`:''}</div><div class="location">${esc(e.location)}</div><p class="copy">${esc(e.text)}</p>${e.note?`<div class="note">${esc(e.note)}</div>`:''}<div class="source">${esc(e.file)}:${e.line}:${e.column}</div></div></article>`).join(''):'<div class="empty">没有匹配项</div>';updateSelection();}
$('list').addEventListener('change',e=>{const id=e.target.dataset.id;if(!id)return;e.target.checked?selected.add(id):selected.delete(id);e.target.closest('article').classList.toggle('selected',e.target.checked);updateSelection();if(mode==='selected')render();});for(const id of ['search','page','type'])$(id).addEventListener(id==='search'?'input':'change',render);
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b===button));$('type').value='';render()}));
function decisionText(){return '请删除以下前端文案：\n'+items.filter(e=>selected.has(e.id)&&!e.deleted_at).map(e=>`${e.id}｜${e.page}｜${e.location}\n${e.text}`).join('\n\n')}
$('copy').addEventListener('click',async()=>{if(!selected.size){$('status').textContent='先勾选待删项';return}try{await navigator.clipboard.writeText('删除 '+items.filter(e=>selected.has(e.id)&&!e.deleted_at).map(e=>e.id).join('、'));$('status').textContent='已复制待删编号'}catch{$('status').textContent='复制不可用，可导出清单'}});
$('download').addEventListener('click',()=>{if(!selected.size){$('status').textContent='先勾选待删项';return}const url=URL.createObjectURL(new Blob([decisionText()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='HayBot-待删文案.txt';a.click();URL.revokeObjectURL(url);$('status').textContent='已导出待删清单'});
$('clear').addEventListener('click',()=>{selected.clear();$('status').textContent='已清空勾选';render()});let dark=matchMedia('(prefers-color-scheme: dark)').matches;try{const stored=localStorage.getItem('haybot-copy-review-theme');if(stored)dark=stored==='dark'}catch{}function theme(){document.documentElement.dataset.theme=dark?'dark':'light';$('theme').textContent=dark?'切换浅色':'切换深色'}$('theme').addEventListener('click',()=>{dark=!dark;theme();try{localStorage.setItem('haybot-copy-review-theme',dark?'dark':'light')}catch{}});theme();render();
</script></body></html>'''
rendered=page.replace('__DATA__',json_text)
# External script works under the production script-src self policy.
start=rendered.index('<script>')
end=rendered.index('</script>',start)
script=rendered[start+len('<script>'):end]
rendered=rendered[:start]+'<script src="review.js" defer></script>'+rendered[end+len('</script>'):]
(p/'review.js').write_text(script)
(p/'index.html').write_text(rendered)
public=p.parents[1]/'frontend'/'public'/'assets'/'copy-review'
public.mkdir(parents=True,exist_ok=True)
(public/'index.html').write_text(rendered)
(public/'review.js').write_text(script)
(p/'README.md').write_text('''# 前端文案审阅\n\n- `index.html`：独立审阅页，默认只看副标题，支持搜索、按页面 / 类型筛选、勾选待删、复制编号、导出。支持明暗主题。不会调用产品 API。正式服务固定地址为 `/assets/copy-review/index.html`。\n- `SUBTITLES.md`：只看副标题。\n- `INVENTORY.md`：完整清单，包含页面、位置、类型、原文与源码行列。\n- `inventory.json`：结构化清单。\n- `extract.cjs` / `build_review.py`：从全部前端 JS / JSX 抽取并生成审阅页。\n\n生成日期：2026-10-28。清单反映 Via 初始化版部署后的前端源码；已按 decisions.json 执行指定删除；保留原文和原编号，并标注已删除状态。动态值以〔表达式〕表示，条件分支以 / 分隔。相同文字出现在不同位置时保留不同编号。补充候选允许包含较长按钮名、辅助访问名称和反馈，以免遗漏；其中不是所有项目都属于副标题。旧 QQ 空间页的副标题定义已标注重定向情况。\n\n范围是产品自带界面文案，覆盖折叠区域、设置标签、弹窗、空状态与失败提示。后台返回的执行结果、模型生成内容、用户填写的配置不是前端固定文案，没有复制真实聊天或日记内容。\n\n回复「删除 T001、T012；T020 改成……」即可。勾选在当前浏览器本地保存，需复制编号或导出后交给开发处理。\n''')
print('Review generated:',len(entries),'entries;',len(subtitles),'subtitle declarations')

md='# 前端文案审阅清单\n\n原始编号固定保留；已删除项目标注状态。动态值以〔表达式〕表示。\n\n'
for group in dict.fromkeys(e['page'] for e in entries):
 md+='## '+group+'\n\n| 编号 | 状态 | 位置 | 类型 | 原文 | 源码 |\n|---|---|---|---|---|---|\n'
 for e in entries:
  if e['page']!=group:continue
  escape=lambda value:str(value).replace('|','\\|').replace('\n','<br>')
  state='已删除 '+e['deleted_at'] if e.get('deleted_at') else '待审阅'
  md+=f"| {e['id']} | {state} | {escape(e['location'])} | {e['type']} | {escape(e['text'])} | {e['file']}:{e['line']}:{e['column']} |\n"
 md+='\n'
(p/'INVENTORY.md').write_text(md.rstrip()+'\n')
